const PLAN_LIMIT_RESOURCES = new Set([
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "webhooks",
]);

function denyNotification(
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
): never {
  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "notification",
    reason: "denied_by_role",
  });
}

/**
 * Inboxes are personal. Reads by the workspace owner stay available so an
 * operator can confirm delivery; every other role, and every write, is only
 * the actor's own rows.
 */
function assertOwnNotification(
  actor: Actor,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
  userId: UserId,
  allowOwnerRead = false,
): void {
  if (userId === actor.userId) return;
  if (allowOwnerRead && action === "notification:read" && actor.role === "owner") {
    return;
  }
  denyNotification(action);
}

async function orgSlug(orgId: OrgId): Promise<string> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? orgId;
}

/** Issue pages live under the workspace and the project, addressed by number. */
async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const slug = await orgSlug(orgId);
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return `/${slug}`;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  const projectSlug = project?.slug ?? issue.projectId;
  return `/${slug}/projects/${projectSlug}/issues/${issue.number}`;
}

async function ownerIds(orgId: OrgId, exceptUserId?: UserId): Promise<UserId[]> {
  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: 100,
    cursor: null,
  });
  return page.items
    .map((member) => member.userId)
    .filter((userId) => userId !== exceptUserId);
}

