function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

input.new_string:
async function hrefFor(
  orgId: OrgId,
  slug: string,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  if (kind === "project") {
    const project = await projectRepo.findProjectById(orgId, subjectId as ProjectId);
    return `/${slug}/projects/${project?.slug ?? subjectId}`;
  }

  const issueId =
    kind === "issue"
      ? (subjectId as IssueId)
      : (await commentRepo.findCommentById(orgId, subjectId as CommentId))?.issueId;

  if (!issueId) return `/${slug}`;

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return `/${slug}`;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return `/${slug}/projects/${project?.slug ?? issue.projectId}/issues/${issue.number}`;
}

