input.new_string:
/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter. Reading the plan ceilings keeps the
 * recount on the same quota table as the write guards, but a recount refuses
 * nothing and must not emit `billing.limit_exceeded`.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (org) getPlanLimits(org.plan);
  return usage;
}

input.old_string:
/**
 * Inboxes are personal. Reads by the workspace owner stay available so an
 * operator can confirm delivery; every other role, and every write, is only
 * the actor's own rows.
 */
function assertOwnNotification(
  actor: Actor,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
  userId: UserId,
  allowOwnerRead = false,
): void {
  if (userId === actor.userId) return;
  if (allowOwnerRead && action === "notification:read" && actor.role === "owner") {
    return;
  }
  denyNotification(action);
}

input.new_string:
/** Inboxes and preferences are personal for every role, including owner. */
function assertOwnNotification(
  actor: Actor,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
