/**
 * Inboxes are personal. A workspace owner may still read another member's
 * inbox (delivery checks); nobody may mark or reconfigure anyone else's.
 */
function assertOwnNotification(
  actor: Actor,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
  userId: UserId,
  allowOwnerRead = false,
): void {
  if (userId === actor.userId) return;
  if (allowOwnerRead && action === "notification:read" && actor.role === "owner") {
    return;
  }
  denyNotification(action);
}

